function escapeHtml(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function makeDayDescription(w,dayIndex){const f=weeklyFormats[dayIndex];return `<p><b>O que estudar:</b> ${escapeHtml(w.activities[dayIndex])}</p><p><b>Recurso:</b> ${escapeHtml(f.resource)}${w.resources?.[dayIndex%w.resources.length]?` · <a href="${w.resources[dayIndex%w.resources.length][1]}" target="_blank" rel="noreferrer">abrir recurso ↗</a>`:''}</p><p><b>Tempo:</b> 15 minutos · <b>Como praticar:</b> ${escapeHtml(f.task)}</p><p><b>Entrega do dia:</b> ${escapeHtml(f.output)}</p>`}
