function makeUsageExamples(term,group){if(examplesByTerm[term.toLowerCase()])return examplesByTerm[term.toLowerCase()];const topic=topicLabels[group]||'everyday life';if(term.includes('?')||/^(I |I’m |I’ve |I’ll |That |Could |Would |How |What |Where |Which |It )/i.test(term))return [`In a real conversation about ${topic}, you could say: “${term}.”`,`I used “${term}” when I was talking with a friend about ${topic}.`];if(adjectiveWords.has(term.toLowerCase())){const noun={home:'apartment',food:'meal',social:'conversation',directions:'street',health:'feeling',work:'schedule',minecraft:'build',technology:'device',programming:'solution',opinions:'choice',stories:'experience',plans:'goal',learning:'practice'}[group]||'day';return [`My ${noun} is ${term} today.`,`The place felt ${term}, so we decided to stay a little longer.`]}const first=term.split(/\s+/)[0].toLowerCase();if(verbHeads.has(first)){const endings={'pick up':'my friend at the station','drop off':'my friend near home','look for':'my keys','look up':'the word in a dictionary','run out of':'coffee','spend time':'with my friends','manage to':'finish the task','need to':'take a short break','have to':'leave soon','would rather':'stay home tonight','follow up':'with my coworker','ask for':'help','apply for':'the position','be responsible for':'the project','check in with':'my teammate','bring up':'the issue','come up with':'a better idea','figure out':'the answer','deal with':'the problem','carry out':'the plan','put off':'the meeting','set up':'my account','turn on':'the device','turn off':'the notifications','get used to':'the new routine','take care of':'the details','keep track of':'my progress','look after':'the kids','pick up groceries':'some groceries','make time for':'my English practice','set aside time':'my study session'};const tail=endings[term.toLowerCase()]||'';if(term.toLowerCase()==='would rather')return ['I’d rather stay home tonight and watch a film.','Would you rather take the bus or walk?'];if(term.toLowerCase()==='used to')return ['I used to walk to work when I lived nearby.','She used to play Minecraft with her brother.'];if(term.toLowerCase()==='get used to')return ['I’m getting used to my new schedule.','It takes time to get used to speaking English every day.'];if(term.toLowerCase()==='manage to')return ['I managed to finish the report before lunch.','Did you manage to find the right bus stop?'];if(term.toLowerCase()==='need to')return ['I need to leave in ten minutes.','We need to check the address before we go.'];if(term.toLowerCase()==='have to')return ['I have to finish this task before lunch.','Do we have to book a table?'];const phrase=tail?`${term} ${tail}`:term;return [`I usually ${phrase} as part of my ${topic}.`,`I sometimes ${phrase} when I have a little free time.`]}return [`I talked about the ${term} with a friend this week.`,`The ${term} came up while we were talking about ${topic}.`]}
async function translateVocab(term){const localMeaning=localMeanings[term.toLowerCase()];if(localMeaning)return localMeaning;if(state.lookups[term])return state.lookups[term];const url=new URL('https://api.mymemory.translated.net/get');url.searchParams.set('q',term);url.searchParams.set('langpair','en|pt-BR');const response=await fetch(url,{headers:{Accept:'application/json'},signal:AbortSignal.timeout(9000)});if(!response.ok)throw new Error('translation unavailable');const data=await response.json();const value=data?.responseData?.translatedText;if(data?.responseStatus!==200||!value||value.toLowerCase().includes('no query specified'))throw new Error('translation unavailable');state.lookups[term]=value;saveState();return value}
async function openVocabCard(button,term,key,group){activeVocabKey=key;const dialog=document.getElementById('vocab-dialog');document.getElementById('vocab-dialog-title').textContent=term;const translation=document.getElementById('vocab-translation');const localMeaning=localMeanings[term.toLowerCase()];translation.textContent=state.lookups[term]||localMeaning||'Buscando tradução…';document.getElementById('vocab-meaning-note').textContent=localMeaning?'Significado contextual deste roteiro; use os exemplos para observar a expressão em situação.':state.lookups[term]?'Tradução automática; considere o contexto da semana para confirmar o sentido.':'Tradução automática para orientar; o contexto ajuda a escolher o sentido.';document.getElementById('vocab-youglish').href=`https://youglish.com/pronounce/${encodeURIComponent(term)}/english`;document.getElementById('vocab-cambridge').href=`https://dictionary.cambridge.org/dictionary/english/${encodeURIComponent(term)}`;document.getElementById('vocab-example-list').innerHTML=makeUsageExamples(term,group).map((example,i)=>`<article class="vocab-example"><span>${i+1}</span><p>${escapeHtml(example)}</p></article>`).join('');const complete=document.getElementById('vocab-complete');complete.textContent=state.vocab[key]?'Concluído ✓ · desfazer':'Concluir';dialog.showModal();if(!state.lookups[term]&&!localMeaning){try{const meaning=await translateVocab(term);if(activeVocabKey===key&&dialog.open){translation.textContent=meaning;document.getElementById('vocab-meaning-note').textContent='Tradução automática; considere o contexto da semana para confirmar o sentido.'}}catch{if(activeVocabKey===key&&dialog.open){translation.textContent='Tradução indisponível agora. Você ainda pode ver os exemplos e consultar o dicionário.';document.getElementById('vocab-meaning-note').textContent='Verifique a conexão ou abra a definição no Cambridge Dictionary.'}}}}
function render(){const root=document.getElementById('weeks-container');root.innerHTML=weeks.map((w,i)=>{const n=i+1;const vocab=vocabSets[w.vocab];return `<article class="week-card ${i===0?'open':''}" data-week="${i}"><button class="week-summary" type="button" aria-expanded="${i===0?'true':'false'}"><span class="week-num">W${String(n).padStart(2,'0')}</span><span><span class="week-title">${escapeHtml(w.theme)}</span><span class="week-subtitle">${escapeHtml(w.subtitle)}</span></span><span class="week-chip">${escapeHtml(w.grammar)}</span><span class="week-chevron">⌄</span></button><div class="week-details"><div class="week-overview"><div class="detail-box"><h4>Foco gramatical</h4><p><b>${escapeHtml(w.grammar)}</b><br>${escapeHtml(w.grammarNote)}</p></div><div class="detail-box"><h4>Conteúdo da semana</h4><p>${escapeHtml(w.content)}</p></div></div><div class="vocab-header"><h4>Vocabulário essencial</h4><span class="vocab-count" data-vocab-count="${i}"></span></div><div class="vocab-list">${vocab.map((term,j)=>{const key=`${i}-${j}`;return `<button class="vocab-item ${state.vocab[key]?'learned':''}" type="button" data-vocab="${key}" aria-pressed="${!!state.vocab[key]}" title="Ver significado e exemplos">${escapeHtml(term)}</button>`}).join('')}</div><div class="week-resources"><b>Materiais e recursos</b>${w.resources.map(r=>`<a href="${r[1]}" target="_blank" rel="noreferrer">${escapeHtml(r[0])} ↗</a>`).join('')}<a href="https://www.bbc.co.uk/learningenglish/english/features/6-minute-english" target="_blank" rel="noreferrer">BBC 6 Minute English ↗</a></div><div class="days-heading">Plano diário · 15 min por sessão</div><div class="day-list">${dayNames.map((day,d)=>{const key=`${i}-${d}`;return `<div class="day-item"><div class="day-trigger"><input class="day-check" type="checkbox" data-day="${key}" aria-label="Marcar ${day} da semana ${n} como concluído" ${state.days[key]?'checked':''}><button type="button" class="day-trigger-main"><span class="day-name">${day}</span><span class="day-focus">${escapeHtml(weeklyFormats[d].name)}</span><span class="day-time">15 min</span><span class="day-toggle">⌄</span></button></div><div class="day-detail">${makeDayDescription(w,d)}</div></div>`}).join('')}</div></div></article>`}).join('');
 root.querySelectorAll('.week-summary').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.week-card');const open=!card.classList.contains('open');card.classList.toggle('open',open);btn.setAttribute('aria-expanded',String(open))}));
 root.querySelectorAll('.day-trigger-main').forEach(btn=>btn.addEventListener('click',()=>btn.closest('.day-item').classList.toggle('expanded')));
 root.querySelectorAll('.day-check').forEach(box=>box.addEventListener('change',()=>{state.days[box.dataset.day]=box.checked;saveState()}));
 root.querySelectorAll('.vocab-item').forEach(btn=>btn.addEventListener('click',()=>{const [weekIndex,termIndex]=btn.dataset.vocab.split('-').map(Number);openVocabCard(btn,vocabSets[weeks[weekIndex].vocab][termIndex],btn.dataset.vocab,weeks[weekIndex].vocab)}));updateProgress()}
function updateProgress(){const completed=Object.values(state.days).filter(Boolean).length;const pct=Math.round(completed/(weeks.length*7)*100);document.getElementById('overall-percent').textContent=`${pct}%`;document.getElementById('overall-bar').style.width=`${pct}%`;document.getElementById('completed-count').textContent=`${completed} de ${weeks.length*7} sessões`;document.querySelectorAll('.vocab-count').forEach(label=>{const weekIndex=Number(label.dataset.vocabCount);const total=vocabSets[weeks[weekIndex].vocab].length;const learned=Array.from({length:total},(_,i)=>state.vocab[`${weekIndex}-${i}`]).filter(Boolean).length;label.textContent=`${learned}/${total} concluídas · clique para ver significado e exemplos`});let current=weeks.length;for(let w=0;w<weeks.length;w++){let weekDone=true;for(let d=0;d<7;d++)if(!state.days[`${w}-${d}`])weekDone=false;if(!weekDone){current=w+1;break}}document.getElementById('week-count').textContent=`Semana ${current} de ${weeks.length}`}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
document.getElementById('export-button').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({app:'english-quest',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='english-quest-backup.json';a.click();URL.revokeObjectURL(a.href);toast('Backup baixado. Guarde o arquivo em local seguro.')});
document.getElementById('import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=JSON.parse(await file.text());const imported=data.state||data;if(!imported.days||!imported.vocab)throw new Error('invalid');state={days:imported.days,vocab:imported.vocab,lookups:imported.lookups||{}};saveState();render();toast('Progresso importado neste navegador.')}catch{toast('Arquivo inválido. Escolha um backup English Quest.')}e.target.value=''});
document.getElementById('vocab-close').addEventListener('click',()=>document.getElementById('vocab-dialog').close());
document.getElementById('vocab-complete').addEventListener('click',()=>{if(!activeVocabKey)return;state.vocab[activeVocabKey]=!state.vocab[activeVocabKey];const button=document.querySelector(`.vocab-item[data-vocab="${activeVocabKey}"]`);if(button){button.classList.toggle('learned',state.vocab[activeVocabKey]);button.setAttribute('aria-pressed',String(state.vocab[activeVocabKey]))}saveState();document.getElementById('vocab-dialog').close()});
document.getElementById('vocab-dialog').addEventListener('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close()});
render();
